+const { parseQuantity } = require('./quantity');
+
+function addToCart(cart, sku, rawQty) {
+  const qty = parseQuantity(rawQty);
+  if (qty === null) throw new Error('invalid quantity: ' + rawQty);
+  cart.push({ sku, qty });
+  return cart;
+}
+
+module.exports = { addToCart };
